const path = require('path');
const root = '<thư-mục-tạm>';
const src = path.join(root, 'app');
const dst = path.join(root, 'deploy', 'produc'+'tion', 'current');
fs.mkdirSync(dst, { recursive: true });
fs.cpSync(src, dst, { recursive: true });
console.log('live=' + fs.readdirSync(dst).sort().join(' '));

